<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder\UserInvitationAcceptedByAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationAcceptedByAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationAcceptedByAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAcceptedBy returns null on a freshly created holder.
     */
    public function testAcceptedByNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedByAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAcceptedByAssigned());
        $this->assertNull($holder->getAcceptedBy());
    }
}
class ImplWithUserInvitationAcceptedByAttributeHolderUnitTest
{
    use UserInvitationAcceptedByAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAcceptedByRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAcceptedBy();
    }
}
